export const LOCAL_STORAGE_KEY_NAME = 'gitprofile-theme';

export const BG_COLOR =
  'bg-linear-to-br from-base-300 via-base-200 to-base-300';

/**
 * Accent classes cycled through by index to give repeated items (skill badges,
 * blog tags) varied color. Each class is written out in full because Tailwind
 * only emits CSS for class names that appear verbatim in the source.
 */
export const ACCENTS = [
  {
    badge: 'badge-primary',
    text: 'text-primary',
    bg: 'bg-primary/10',
    border: 'border-primary/40',
  },
  {
    badge: 'badge-secondary',
    text: 'text-secondary',
    bg: 'bg-secondary/10',
    border: 'border-secondary/40',
  },
  {
    badge: 'badge-accent',
    text: 'text-accent',
    bg: 'bg-accent/10',
    border: 'border-accent/40',
  },
  {
    badge: 'badge-info',
    text: 'text-info',
    bg: 'bg-info/10',
    border: 'border-info/40',
  },
  {
    badge: 'badge-success',
    text: 'text-success',
    bg: 'bg-success/10',
    border: 'border-success/40',
  },
  {
    badge: 'badge-warning',
    text: 'text-warning',
    bg: 'bg-warning/10',
    border: 'border-warning/40',
  },
] as const;

export const accentAt = (index: number) => ACCENTS[index % ACCENTS.length];

/**
 * Surface and hover treatment shared by every clickable item card (repos,
 * articles, external projects, publications) so all four sections animate
 * identically. `transition-all` rather than `transition-transform` so the
 * shadow grows with the lift instead of snapping.
 */
export const ITEM_CARD_CLASS =
  'card card-sm bg-base-100 border border-base-300 shadow-md h-full transition-all duration-200 hover:-translate-y-1 hover:shadow-lg hover:border-base-content/10 motion-reduce:transform-none';

export const FALLBACK_IMAGE =
  'data:image/png;base64,';
